(async () => {
  // Find the path to the main content script asset generated by Vite
  // This relies on the entry point name in vite.config.ts ('content_script')
  // Note: This assumes only one JS file matching the pattern.
  // Adjust if your build outputs multiple content script related files.
  const src = chrome.runtime.getURL('assets/content_script.js');

  try {
    // Dynamically import the content script as a module
    await import(src);
    console.log('Content script loaded dynamically.');
  } catch (e) {
    console.error('Error loading dynamic content script:', e);
  }
})(); 